const rawData = $input.first().json.data || '';
const trigger = $('When Executed by Another Workflow').first().json || {};

const matches = [...String(rawData).matchAll(/"videoId":"([a-zA-Z0-9_-]{11})"/g)].map(m => m[1]);
const uniqueIds = [...new Set(matches)].slice(0, 5);

return uniqueIds.map(id => ({
  json: {
    video_id: id,
    video_url: `https://www.youtube.com/watch?v=${id}`,
    keyword: trigger.keyword || '',
    country: trigger.country || ''
  }
}));

