const inputs = $input.all();
const videoItems = $('Code (영상 URL 추출)').all();

const out = [];
inputs.forEach((item, idx) => {
  const vInfo = videoItems[idx]?.json || {};
  const parts = item.json?.candidates?.[0]?.content?.parts || [];
  const summaryText = parts.map(p => p.text || '').join('\n').trim();
  if (summaryText.length <= 20) return;   // Gemini 실패/빈 응답은 건너뜀

  out.push({
    json: {
      voc_id: `YT_${vInfo.video_id || idx}`,
      source_site: 'YouTube',
      site_name: 'YouTube',
      category: 'Video/YouTube',
      content_type: 'VIDEO',
      content: summaryText,
      parent_id: vInfo.video_url || '',
      source_url: vInfo.video_url || '',
      country: vInfo.country || '',
      keyword: vInfo.keyword || '',
      published_at: new Date().toISOString()
    }
  });
});
return out;
